-- Default catalog + estimate templates from the master's tetris price lists
-- (Будівельні + Внутрішні роботи). Generated offline via vision extraction, deduped
-- against the existing default catalog (punctuation-insensitive), no duplicates introduced.
--
-- Rules (agreed): everything from tetris becomes estimate templates (23 sections → 23
-- default bundles). Prices: an existing catalog position with a non-zero price keeps it
-- (data-sacred, pulled into estimates); a NEW position or an existing one priced 0 takes
-- the tetris price. Templates carry no price — resolved from each master's catalog by name.
-- Lump-sum "комплекс на весь об'єкт" sections (НАВІС / ГАРАЖ / ХОЗ БЛОК) were excluded.

-- 201 NEW default catalog positions (tetris price + trade, version 5)

-- 23 default estimate templates (bundles), one per tetris section
WITH t AS (
)
SELECT gen_random_uuid(), t.id, v.name, 'WORK', v.unit, v.ord FROM t, (VALUES ('Планування ділянки і нівелювання - від', 'PIECE', 0), ('Перенесення землі (не далі 20м)', 'M3', 1), ('Копання траншей ям котловану вручну', 'M3', 2), ('Планування грунту до 10 см', 'M2', 3), ('Копка траншей глибиною 0,5 м і шириною 35см', 'LINEAR_METER', 4), ('Зворотня засипка траншеї', 'M3', 5), ('Піщана подушка з ущільненням', 'M2', 6), ('Щебенева підготовка до 10 см', 'M2', 7)) AS v(name, unit, ord);

